contract InvMutTest is Test {
    GameItems c;
    function setUp() public { c = new GameItems(address(this), address(this)); }

    function testFuzz_property(address account, uint256 tokenId, uint256 amount) public {
        vm.assume(account != address(0));
        uint256 id = tokenId % 10;
        uint256 amt = amount % 100;

        c.createGameItem("item", "uri", true, true, 1000, 1, 10);

        MockNeuron mock = new MockNeuron();
        c.instantiateNeuronContract(address(mock));

        mock.mint(account, 1000);

        vm.prank(account);
        if (amt > 0) {
            try c.mint(0, amt) {
            } catch {
            }
        }

        address[] memory accounts = new address[](1);
        uint256[] memory ids = new uint256[](1);
        accounts[0] = account;
        ids[0] = id;

        uint256[] memory batch = c.balanceOfBatch(accounts, ids);
        uint256 single = c.balanceOf(account, id);

        assertTrue(batch[0] == single);
    }
}

contract MockNeuron {
    mapping(address => uint256) public balances;
    mapping(address => mapping(address => uint256)) public allowances;

    function mint(address to, uint256 amount) external {
        balances[to] += amount;
    }

    function balanceOf(address account) external view returns (uint256) {
        return balances[account];
    }

    function approveSpender(address account, uint256 amount) external {
        allowances[account][msg.sender] = amount;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        if (balances[from] < amount) return false;
        if (allowances[from][msg.sender] < amount) return false;
        balances[from] -= amount;
        balances[to] += amount;
        return true;
    }

}
